// --- MODERN CUSTOM PERSONNEL SELECT COMBOBOX ---
const ModernPersonnelSelect: React.FC<{
  label: string;
  labelColor: string;
  icon: React.ReactNode;
  value: string;
  onChange: (val: string) => void;
  personnelList?: PersonnelItem[];
  roleFilter?: string[];
  accentColor?: 'blue' | 'amber' | 'emerald';
  placeholder?: string;
}> = ({ label, labelColor, icon, value, onChange, personnelList = [], roleFilter, accentColor = 'blue', placeholder = '— Pilih Personil —' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filtered = personnelList.filter(p => {
    if (!roleFilter || roleFilter.length === 0) return true;
    return roleFilter.includes(p.role) || !p.role;
  });

  const matchingItems = filtered.filter(p => p.name.toLowerCase().includes((value || '').toLowerCase()));

  const themeStyles = {
    blue: 'focus-within:border-blue-500 focus-within:ring-1 focus-within:ring-blue-500',
    amber: 'focus-within:border-amber-500 focus-within:ring-1 focus-within:ring-amber-500',
    emerald: 'focus-within:border-emerald-500 focus-within:ring-1 focus-within:ring-emerald-500',
  }[accentColor];

  return (
    <div ref={containerRef} className="relative w-full">
      <label className={`text-[9.5px] font-bold uppercase tracking-wider ${labelColor} mb-0.5 flex items-center gap-1`}>
        {icon}
        <span>{label}</span>
      </label>
      
      <div className={`relative flex items-center bg-white border border-slate-300 rounded-lg shadow-2xs transition-all ${themeStyles}`}>
        <input
          type="text"
          value={value}
          onChange={e => {
            onChange(e.target.value);
            setIsOpen(true);
          }}
          onFocus={() => setIsOpen(true)}
          placeholder={placeholder}
          className="w-full bg-transparent px-2.5 py-1 font-bold text-slate-900 text-xs outline-none pr-7 placeholder:text-slate-400 placeholder:font-normal"
        />
        
        <div className="absolute right-2 flex items-center gap-1 pointer-events-none text-slate-400">
          <ChevronDown className={`w-3.5 h-3.5 transition-transform duration-200 ${isOpen ? 'rotate-180 text-slate-600' : ''}`} />
        </div>
      </div>

      {/* MODERN FLOATING DROPDOWN MENU */}
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-1 z-50 bg-white/95 backdrop-blur-xl border border-slate-200/90 rounded-xl shadow-xl p-1 max-h-56 overflow-y-auto space-y-0.5 animate-in fade-in slide-in-from-top-1 duration-150">
          <button
            type="button"
            onClick={() => {
              onChange('');
              setIsOpen(false);
            }}
            className="w-full text-left px-2.5 py-1.5 rounded-lg text-xs transition flex items-center gap-2 hover:bg-slate-100 text-slate-400 hover:text-slate-700 italic border-b border-slate-100 cursor-pointer"
          >
            <span>— Kosongkan (Belum Dipilih) —</span>
          </button>
          {matchingItems.length === 0 ? (
            <div className="px-3 py-2 text-[11px] text-slate-400 italic text-center">
              Ketik nama kustom...
            </div>
          ) : (
            matchingItems.map(p => (
              <button
                key={p.id}
                type="button"
                onClick={() => {
                  onChange(p.name);
                  setIsOpen(false);
                }}
                className={`w-full text-left px-2.5 py-1.5 rounded-lg text-xs transition flex items-center justify-between group cursor-pointer ${
                  value === p.name ? 'bg-emerald-50 text-emerald-900 font-bold' : 'hover:bg-slate-100/80 text-slate-700'
                }`}
              >
                <div className="flex items-center gap-2">
                  <div className="w-6 h-6 rounded-full bg-slate-100 border border-slate-200 text-slate-600 font-bold text-[10px] flex items-center justify-center shrink-0 uppercase">
                    {p.name.charAt(0)}
                  </div>
                  <div>
                    <div className="font-extrabold text-slate-800 text-[11px] group-hover:text-emerald-700">{p.name}</div>
                    {p.title && <div className="text-[9.5px] text-slate-400 font-medium">{p.title}</div>}
                  </div>
                </div>
                {p.role && (
                  <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-slate-100 text-slate-500 border border-slate-200/60">
                    {p.role}
                  </span>
                )}
              </button>
            ))
          )}
        </div>
      )}
    </div>
  );
};

// --- MODERN CUSTOM DATE PICKER COMPONENT (REACT CALENDAR POPOVER) ---
const ModernDatePicker: React.FC<{
  label: string;
  value: string;
  onChange: (val: string) => void;
  accentColor?: 'blue' | 'emerald';
}> = ({ label, value, onChange, accentColor = 'blue' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const selectedDate = value ? new Date(value + 'T00:00:00') : null;
  const [viewDate, setViewDate] = useState<Date>(() => selectedDate || new Date());

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (value) {
      setViewDate(new Date(value + 'T00:00:00'));
    }
  }, [value]);

  const handlePrevMonth = (e: React.MouseEvent) => {
    e.stopPropagation();
    setViewDate(prev => new Date(prev.getFullYear(), prev.getMonth() - 1, 1));
  };

  const handleNextMonth = (e: React.MouseEvent) => {
    e.stopPropagation();
    setViewDate(prev => new Date(prev.getFullYear(), prev.getMonth() + 1, 1));
  };

  const handleSelectDay = (day: number) => {
    const year = viewDate.getFullYear();
    const month = String(viewDate.getMonth() + 1).padStart(2, '0');
    const dayStr = String(day).padStart(2, '0');
    const fullDate = `${year}-${month}-${dayStr}`;
    onChange(fullDate);
    setIsOpen(false);
  };

  const handleSetToday = (e: React.MouseEvent) => {
    e.stopPropagation();
    const today = new Date();
    const year = today.getFullYear();
    const month = String(today.getMonth() + 1).padStart(2, '0');
    const dayStr = String(today.getDate()).padStart(2, '0');
    const fullDate = `${year}-${month}-${dayStr}`;
    setViewDate(today);
    onChange(fullDate);
    setIsOpen(false);
  };

  const handleClear = (e: React.MouseEvent) => {
    e.stopPropagation();
    onChange('');
    setIsOpen(false);
  };

  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const monthNames = [
    'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
    'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
  ];
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfWeek = new Date(year, month, 1).getDay();

  const today = new Date();
  const isCurrentMonthToday = today.getFullYear() === year && today.getMonth() === month;
  const todayDateNum = today.getDate();

  const themeStyles = {
    blue: {
      border: 'focus-within:border-blue-500 focus-within:ring-1 focus-within:ring-blue-500',
      icon: 'text-blue-600',
      badge: 'bg-blue-50 text-blue-700 hover:bg-blue-100 border-blue-200',
      selectedDay: 'bg-gradient-to-r from-blue-600 to-teal-600 text-white font-black shadow-md shadow-blue-500/25'
    },
    emerald: {
      border: 'focus-within:border-emerald-500 focus-within:ring-1 focus-within:ring-emerald-500',
      icon: 'text-emerald-600',
      badge: 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border-emerald-200',
      selectedDay: 'bg-gradient-to-r from-emerald-600 to-teal-600 text-white font-black shadow-md shadow-emerald-500/25'
    }
  }[accentColor];

  const getFormattedDateStr = (dateStr: string) => {
    if (!dateStr) return '';
    try {
      const parts = dateStr.split('-');
      if (parts.length === 3) {
        const d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
        return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
      }
    } catch {
      return dateStr;
    }
    return dateStr;
  };

  const formattedStr = getFormattedDateStr(value);

  return (
    <div ref={containerRef} className="relative w-full">
      <label className="text-[9.5px] font-bold uppercase tracking-wider text-slate-600 mb-0.5 flex items-center justify-between">
        <div className="flex items-center gap-1">
          <Calendar className={`w-3 h-3 ${themeStyles.icon}`} />
          <span>{label}</span>
        </div>
        <button
          type="button"
          onClick={handleSetToday}
          className={`text-[9px] font-bold px-1.5 py-0.2 rounded border transition cursor-pointer ${themeStyles.badge}`}
          title="Set tanggal hari ini"
        >
          Hari Ini
        </button>
      </label>

      {/* INPUT TRIGGER BOX */}
      <div
        onClick={() => setIsOpen(!isOpen)}
        className={`relative flex items-center bg-white border border-slate-300 rounded-lg px-2.5 py-1 shadow-2xs transition-all cursor-pointer select-none ${themeStyles.border}`}
      >
        <Calendar className={`w-3.5 h-3.5 mr-2 shrink-0 ${themeStyles.icon}`} />
        
        {/* Display formatted date text */}
        <div className="w-full font-bold text-xs font-mono text-slate-900">
          {formattedStr ? (
            <span className="text-slate-900 font-extrabold">{formattedStr}</span>
          ) : (
            <span className="text-slate-400 font-normal italic">Pilih tanggal...</span>
          )}
        </div>

        <ChevronDown className={`w-3.5 h-3.5 text-slate-400 transition-transform duration-200 ${isOpen ? 'rotate-180 text-slate-600' : ''}`} />
      </div>

      {/* MODERN GLASSMORPHIC FLOATING CALENDAR POPOVER */}
      {isOpen && (
        <div className="absolute top-full left-0 mt-1.5 z-50 bg-white/95 backdrop-blur-xl border border-slate-200/90 rounded-2xl shadow-2xl p-3.5 w-72 animate-in fade-in slide-in-from-top-2 duration-150 text-slate-800">
          
          {/* CALENDAR HEADER (MONTH / YEAR NAVIGATION) */}
          <div className="flex items-center justify-between mb-3 border-b border-slate-100 pb-2">
            <button
              type="button"
              onClick={handlePrevMonth}
              className="p-1.5 text-slate-500 hover:text-slate-900 hover:bg-slate-100 rounded-lg transition cursor-pointer"
              title="Bulan Sebelumnya"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <div className="font-extrabold text-slate-900 text-xs tracking-tight">
              {monthNames[month]} {year}
            </div>
            <button
              type="button"
              onClick={handleNextMonth}
              className="p-1.5 text-slate-500 hover:text-slate-900 hover:bg-slate-100 rounded-lg transition cursor-pointer"
              title="Bulan Berikutnya"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>

          {/* DAY NAMES HEADER */}
          <div className="grid grid-cols-7 gap-1 text-center font-bold text-[10px] text-slate-400 mb-1.5 uppercase tracking-wider">
            <span>Min</span>
            <span>Sen</span>
            <span>Sel</span>
            <span>Rab</span>
            <span>Kam</span>
            <span>Jum</span>
            <span>Sab</span>
          </div>

          {/* DAYS GRID */}
          <div className="grid grid-cols-7 gap-1 text-xs">
            {/* Empty slots before first day */}
            {Array.from({ length: firstDayOfWeek }).map((_, idx) => (
              <div key={`empty-${idx}`} />
            ))}

            {/* Month days */}
            {Array.from({ length: daysInMonth }).map((_, idx) => {
              const dayNum = idx + 1;
              const isSelected =
                selectedDate &&
                selectedDate.getFullYear() === year &&
                selectedDate.getMonth() === month &&
                selectedDate.getDate() === dayNum;

              const isToday = isCurrentMonthToday && todayDateNum === dayNum;

              return (
                <button
                  key={`day-${dayNum}`}
                  type="button"
                  onClick={() => handleSelectDay(dayNum)}
                  className={`h-8 w-8 mx-auto flex items-center justify-center rounded-xl font-bold transition cursor-pointer ${
                    isSelected
                      ? themeStyles.selectedDay
                      : isToday
                      ? 'border border-blue-500 text-blue-700 bg-blue-50/50 hover:bg-blue-100'
                      : 'hover:bg-slate-100 text-slate-700'
                  }`}
                >
                  {dayNum}
                </button>
              );
            })}
          </div>

          {/* CALENDAR FOOTER (ACTION BUTTONS) */}
          <div className="flex items-center justify-between mt-3 pt-2 border-t border-slate-100 text-[11px] font-bold">
            <button
              type="button"
              onClick={handleClear}
              className="text-slate-400 hover:text-red-600 transition cursor-pointer"
            >
              Hapus
            </button>
            <button
              type="button"
              onClick={handleSetToday}
              className="text-emerald-700 hover:text-emerald-800 transition cursor-pointer font-extrabold"
            >
              Hari Ini
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

// --- MODERN CUSTOM SOIL COLOUR SELECT (BILINGUAL USCS POPOVER) ---
export const ModernSoilColourSelect: React.FC<{
  value: number;
  onChange: (code: number, name: string) => void;
  activeTestSubTab?: string;
}> = ({ value, onChange, activeTestSubTab }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const selectedObj = SOIL_COLOUR_CATALOGUE.find(c => c.code === value) || SOIL_COLOUR_CATALOGUE[0];
  const [selectedId, selectedEn] = selectedObj.name.includes('/')
    ? selectedObj.name.split('/').map(s => s.trim())
    : [selectedObj.name, ''];

  const filtered = SOIL_COLOUR_CATALOGUE.filter(c => {
    if (!searchTerm.trim()) return true;
    const term = searchTerm.toLowerCase();
    return c.name.toLowerCase().includes(term);
  });

  return (
    <div ref={containerRef} className="relative w-full">
      {/* TRIGGER BUTTON */}
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className={`w-full text-left bg-white border ${
          isOpen ? 'border-teal-500 ring-2 ring-teal-500/20' : 'border-slate-300 hover:border-slate-400'
        } rounded-xl px-3 py-2 shadow-2xs transition-all flex items-center justify-between gap-2 cursor-pointer`}
      >
        <div className="flex items-center gap-2.5 min-w-0">
          <span
            className="w-4 h-4 rounded-full border border-slate-300 shrink-0 shadow-xs ring-2 ring-white"
            style={{ backgroundColor: selectedObj.hex }}
          />
          <div className="flex items-center gap-1.5 truncate">
            <span className="font-extrabold text-slate-800 text-xs truncate">
              {selectedId}
            </span>
            {selectedEn && (
              <span className="text-[10px] text-teal-700 bg-teal-50 border border-teal-200/80 px-1.5 py-0.2 rounded-md font-mono font-bold italic shrink-0">
                {selectedEn}
              </span>
            )}
          </div>
        </div>

        <div className="flex items-center gap-1 text-slate-400 shrink-0">
          <ChevronDown className={`w-4 h-4 transition-transform duration-200 ${isOpen ? 'rotate-180 text-teal-600' : ''}`} />
        </div>
      </button>

      {/* FLOATING POPOVER DROPDOWN */}
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-1.5 z-50 bg-white/98 backdrop-blur-xl border border-slate-200/90 rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.18)] p-2 max-h-72 overflow-y-auto space-y-1.5 animate-in fade-in zoom-in-95 duration-150 select-none">
          {/* SEARCH INPUT */}
          <div className="relative mb-1">
            <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Cari warna tanah (cth: cokelat, abu, merah)..."
              className="w-full bg-slate-50 border border-slate-200 rounded-lg pl-8 pr-2.5 py-1.5 text-xs font-semibold text-slate-800 focus:outline-none focus:border-teal-500 placeholder:text-slate-400"
              autoFocus
            />
          </div>

          {/* COLOR LIST */}
          <div className="space-y-0.5 max-h-52 overflow-y-auto pr-0.5">
            {filtered.length === 0 ? (
              <div className="py-4 text-center text-xs text-slate-400 italic">
                Warna tidak ditemukan.
              </div>
            ) : (
              filtered.map((c) => {
                const [idPart, enPart] = c.name.includes('/')
                  ? c.name.split('/').map(s => s.trim())
                  : [c.name, ''];
                const isSelected = value === c.code;

                return (
                  <button
                    key={c.code}
                    type="button"
                    onClick={() => {
                      onChange(c.code, c.name);
                      setIsOpen(false);
                    }}
                    className={`w-full text-left px-2.5 py-2 rounded-xl transition flex items-center justify-between group cursor-pointer ${
                      isSelected
                        ? 'bg-teal-50 text-teal-900 border border-teal-200/70 font-bold'
                        : 'hover:bg-slate-100 text-slate-700'
                    }`}
                  >
                    <div className="flex items-center gap-2.5 min-w-0">
                      <span
                        className="w-5 h-5 rounded-full border border-slate-300 shrink-0 shadow-xs ring-2 ring-white"
                        style={{ backgroundColor: c.hex }}
                      />
                      <div className="min-w-0 flex items-center gap-1.5 truncate">
                        <span className="font-bold text-xs text-slate-900 truncate group-hover:text-teal-900">
                          {idPart}
                        </span>
                        {enPart && (
                          <span className="text-[10px] text-slate-500 font-medium italic group-hover:text-teal-700 truncate">
                            ({enPart})
                          </span>
                        )}
                      </div>
                    </div>

                    {isSelected && (
                      <Check className="w-4 h-4 text-teal-600 shrink-0" />
                    )}
                  </button>
                );
              })
            )}
          </div>
        </div>
      )}
    </div>
  );
};

