const WATER_DENSITY_TABLE: { [temp: number]: { density: number; kFactor: number } } = {
  18: { density: 0.9986244, kFactor: 1.0004 },
  19: { density: 0.9984347, kFactor: 1.0002 },
  20: { density: 0.9982343, kFactor: 1.0000 },
  21: { density: 0.9980233, kFactor: 0.9998 },
  22: { density: 0.9978019, kFactor: 0.9996 },
  23: { density: 0.9975702, kFactor: 0.9993 },
  24: { density: 0.9973286, kFactor: 0.9991 },
  25: { density: 0.9970770, kFactor: 0.9989 },
  26: { density: 0.9968156, kFactor: 0.9986 },
  27: { density: 0.9965451, kFactor: 0.9983 },
  28: { density: 0.9962652, kFactor: 0.9980 },
  29: { density: 0.9959761, kFactor: 0.9977 },
  30: { density: 0.9956780, kFactor: 0.9974 }
};

export const getWaterTempProperties = (tempInput: string | number): { density: number; kFactor: number } => {
  const cleanStr = String(tempInput || '').replace(',', '.');
  const temp = parseFloat(cleanStr);
  
  if (isNaN(temp)) return WATER_DENSITY_TABLE[23];

  if (temp <= 18) return WATER_DENSITY_TABLE[18];
  if (temp >= 30) return WATER_DENSITY_TABLE[30];

  const lowerTemp = Math.floor(temp);
  const upperTemp = Math.ceil(temp);

  if (lowerTemp === upperTemp) {
    return WATER_DENSITY_TABLE[lowerTemp] || WATER_DENSITY_TABLE[23];
  }

  const lowerObj = WATER_DENSITY_TABLE[lowerTemp] || WATER_DENSITY_TABLE[23];
  const upperObj = WATER_DENSITY_TABLE[upperTemp] || WATER_DENSITY_TABLE[23];

  const fraction = (temp - lowerTemp) / (upperTemp - lowerTemp);

  const density = lowerObj.density + fraction * (upperObj.density - lowerObj.density);
  const kFactor = lowerObj.kFactor + fraction * (upperObj.kFactor - lowerObj.kFactor);

  return { density, kFactor };
};

