// Helper functions for Equipment / Calibration Catalog Validation
export const validateContainerCode = (catalogue: ContainerItem[], code: string, isDsTest?: boolean) => {
  const clean = (code || '').trim().toUpperCase();
  if (!clean) return { found: null, isValid: true };

  // For DS tests, numeric container codes are strictly forbidden!
  if (isDsTest && (!isNaN(Number(clean)) || /^\d+$/.test(clean))) {
    return { found: null, isValid: false };
  }

  const found = (catalogue || []).find(c => {
    const itemCode = String(c.id || (c as any).cawanNo || (c as any).noCawan || (c as any).kode || '').trim().toUpperCase();
    if (isDsTest && /^\d+$/.test(itemCode)) return false;
    return itemCode === clean;
  });

  if (found) return { found, isValid: true };

  // Fallback to static DS_CAWAN_CATALOGUE if available
  if (DS_CAWAN_CATALOGUE[clean] !== undefined) {
    return {
      found: { id: clean, weight: DS_CAWAN_CATALOGUE[clean] } as ContainerItem,
      isValid: true
    };
  }

  // If container code is not found in master catalogue or DS_CAWAN_CATALOGUE, return invalid with no found item
  return {
    found: null,
    isValid: false
  };
};

export const validatePycCode = (catalogue: PycnometerItem[], code: string) => {
  const clean = (code || '').trim().toUpperCase();
  if (!clean) return { found: null, isValid: true };
  const found = (catalogue || []).find(p =>
    String(p.pycNo || (p as any).noPiknometer || p.id || '').trim().toUpperCase() === clean
  );
  return { found: found || null, isValid: !!found };
};

