                        <td className="px-2 h-9 align-middle"><input type="number" step="0.001" placeholder="0.000" value={sgA2} onChange={e => { setSgA2(e.target.value); markDirty(); }} className="w-full h-7 bg-white border border-slate-300 rounded-lg px-2 py-0 text-center font-semibold text-slate-900 text-xs focus:border-blue-500" /></td>
