                        const hasDS_CD = isTestAssigned('DS-CD') || isTestAssigned('DS-CD-RES') || isTestAssigned('DS-CU');
                        const hasUCT = isTestAssigned('UCT');
                        const hasTRX_UU = isTestAssigned('TRX-UU') || isTestAssigned('TRX');
                        const hasTRX_CU = isTestAssigned('TRX-CU');
                        const hasTRX_CD = isTestAssigned('TRX-CD');
                        const hasPRM = isTestAssigned('PRM') || isTestAssigned('PB');
                        const hasCT = isTestAssigned('CT') || isTestAssigned('CNS') || isTestAssigned('CONSOL');
                        const hasCMP = isTestAssigned('CMP-STD') || isTestAssigned('CMP-MOD') || isTestAssigned('CMP');
                        const hasCBR = isTestAssigned('CBR') || isTestAssigned('CBR-UNS') || isTestAssigned('CBR-SOK');

